let tabuleiro = Array(9).fill(null);
let vez = 'X';

function jogar(i) {
  if (tabuleiro[i] !== null) return;   // casa ocupada: ignora (módulo 2)
  tabuleiro[i] = vez;
  vez = (vez === 'X') ? 'O' : 'X';     // alterna
}

let fim = false;

function jogar(i) {
  if (fim) return;                     // jogo encerrado
  if (tabuleiro[i] !== null) return;   // casa ocupada
  tabuleiro[i] = vez;                  // marca
  // (checar vitória — módulo 3)
  vez = (vez === 'X') ? 'O' : 'X';     // só agora troca a vez
}

const TRINCAS = [[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];

function vencedor(tab) {
  for (const [a,b,c] of TRINCAS) {
    if (tab[a] && tab[a] === tab[b] && tab[b] === tab[c]) return tab[a];
  }
  return null;   // ninguém venceu ainda
}
function empate(tab) {
  return !vencedor(tab) && tab.every(c => c !== null);
}
